// Security review of round 30: withinShrunk, driven directly. A dark region only part of which a
// light paint covers is not repainted when the uncovered part is more than a tenth of it: a
// 0.07-high strip whitened only in its middle 0.03, a 1/64 strip with white beside it.
func TestPDFWithinShrunkLeavesNoUncoveredDark(t *testing.T) {
	t.Parallel()
	for name, c := range map[string]struct {
		region, light [4]float64
		covered       bool
	}{
		"a 0.07 strip whitened in its middle 0.03": {[4]float64{72, 300, 130, 300.07}, [4]float64{70, 300.02, 132, 300.05}, false},
		"a 1/64 strip with white beside it":        {[4]float64{72, 300, 130, 300.015625}, [4]float64{70, 300.015625, 132, 300.017578125}, false},
		"a 0.07 strip whitened exactly":            {[4]float64{72, 300, 130, 300.07}, [4]float64{72, 300, 130, 300.07}, true},
		"a large mark whitened within the margin":  {[4]float64{72, 300, 130, 310}, [4]float64{72.01, 300.01, 129.99, 309.99}, true},
		"a large mark whitened 0.5 short":          {[4]float64{72, 300, 130, 310}, [4]float64{72.5, 300, 130, 310}, false},
		"an empty region":                          {[4]float64{72, 300, 72, 300}, [4]float64{0, 0, 612, 792}, false},
	} {
		if got := withinShrunk(c.region, c.light); got != c.covered {
			t.Errorf("%s: covered %v, want %v", name, got, c.covered)
		}
	}
}
